CREATE POLICY "map art read own" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'map-art' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "map art insert own" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'map-art' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "map art update own" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'map-art' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "map art delete own" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'map-art' AND (storage.foldername(name))[1] = auth.uid()::text);